    function run(uint amount, address recipient) public payable {
        require(address(this).balance >= amount);
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);
        uint balBefore = address(c).balance;
        bool isOwner = (c.owner() == address(this));
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        assert(isOwner ? (!reverted && address(c).balance == 0) : (reverted && address(c).balance == balBefore));
    }
    receive() external payable {}
    fallback() external payable {}
